import{z as A,x as s,o as t,c as h,q as i,j as B,D as e,d as l,s as o,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"亥姆霍兹与惠更斯–菲涅尔","description":"","frontmatter":{"title":"亥姆霍兹与惠更斯–菲涅尔","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/helmholtz-huygens.md","filePath":"litho/helmholtz-huygens.md","lastUpdated":1791413859000}'),p={name:"litho/helmholtz-huygens.md"};function d(m,a,f,D,c,u){const r=s("Mermaid");return t(),h("div",null,[a[2]||(a[2]=i('<h1 id="亥姆霍兹与惠更斯–菲涅尔" tabindex="-1">亥姆霍兹与惠更斯–菲涅尔 <a class="header-anchor" href="#亥姆霍兹与惠更斯–菲涅尔" aria-label="Permalink to &quot;亥姆霍兹与惠更斯–菲涅尔&quot;">​</a></h1><div class="epigraph"><p>亥姆霍兹方程约束单色场在每一点如何弯曲；惠更斯–菲涅尔积分把一块已知孔径上的场，写成下游每一点的二次子波叠加。</p><footer>—— 据 Born &amp; Wolf, Principles of Optics 对标量衍射的 Kirchhoff / 惠更斯–菲涅尔表述整理</footer></div><p><a href="/litho/em-wave-index">上一课</a>已经把单色复振幅 \\(U\\)、折射率 \\(n\\) 和光程钉死，\\(U\\) 满足亥姆霍兹方程 \\((\\nabla^2+n^2 k_0^2)U=0\\)。缺口是：方程是局部的，掩模开口却是一块有限边界。只说「平面波是特解」，算不出缝后面某处的场。本课把亥姆霍兹收成衍射积分；空间频率怎么给这些子波命名，留给<a href="/litho/diffraction-spatial-freq">衍射与空间频率</a>。不要从瑞利判据起笔：那条产线公式还没有光瞳，更没有积分核。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>均匀介质里亥姆霍兹处处成立，但光刻要的是「已知物面透过率，求像面前的场」。这是边值问题。惠更斯的图像是：波前上每一点当作新的球面子波源；菲涅尔补上倾斜因子，使正前方贡献大、擦边方向贡献小。没有这层积分，后课的角谱只是换基底，推导从哪块面积出发并不清楚。</p><p><span class="marginnote">直觉类比：把波前想成一排水面上等间距的浮标，每个浮标同时在按各自的相位上下晃、往外圈圈涟漪。下游任意一点的水高，就是所有涟漪在该点叠加的结果——「已知浮标，算远处水高」就是惠更斯–菲涅尔积分干的事。</span></p><p>缺口因此是给上一课的 \\(U\\) 一个从孔径走到观察点的核，而不是重讲 \\(n\\) 与光程。光程仍然进入相位：子波走过的几何程乘 \\(n\\)，再乘 \\(k_0\\)，与第一课同一套符号。</p><h3 id="积分核不是又一个折射率" tabindex="-1">积分核不是又一个折射率 <a class="header-anchor" href="#积分核不是又一个折射率" aria-label="Permalink to &quot;积分核不是又一个折射率&quot;">​</a></h3><p>Kirchhoff 用格林定理把亥姆霍兹变成面积分：观察点场由孔径上的 \\(U\\) 与 \\(\\partial U/\\partial n\\) 决定。惠更斯–菲涅尔是它的常用近似——孔径上每面元贡献 \\(\\propto U(\\mathbf{r}&#39;)\\,e^{ikr}/r\\)，再乘倾斜因子。\\(n\\) 已经在 \\(k=nk_0\\) 里；不要把「子波强度」误写成新的材料参数。</p><p><span class="marginnote">本课仍是标量。偏振边界条件、掩模吸收体厚度，会改孔径上的 \\(U\\) 本身，那是后课的电磁缺口。这里假定薄物面已经给出了标量 \\(U\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>约定物面在 \\(z=0\\)，观察点在 \\(z\\gt 0\\)。惠更斯–菲涅尔（菲涅尔近似下）把场写成</p> \\[U(x,y,z)\\propto \\iint U(x&#39;,y&#39;,0)\\,\\frac{e^{ikR}}{R}\\,K(\\theta)\\,dx&#39;dy&#39;, \\]<p>\\(R\\) 是面元到观察点的距离，\\(K(\\theta)\\) 是倾斜因子。\\(k\\) 里的 \\(n\\) 来自上一课。当 \\(z\\) 远大于孔径、且横向频率不太高，相位里的 \\(R\\) 可展到二次项（菲涅尔）或只留线性项（夫琅禾费）。投影物镜的光瞳平面，正是把物面场送到夫琅禾费域的那一段。</p><p>Rayleigh–Sommerfeld 把 Kirchhoff 的边界矛盾收掉，核更干净；光刻仿真里角谱传播与它等价：每个平面波分量乘 \\(\\exp(ik_z z)\\)。本课不展开算法，只承认：亥姆霍兹加上辐射条件，唯一地决定了这块积分。</p><h3 id="近场与远场是同一积分的两个极限" tabindex="-1">近场与远场是同一积分的两个极限 <a class="header-anchor" href="#近场与远场是同一积分的两个极限" aria-label="Permalink to &quot;近场与远场是同一积分的两个极限&quot;">​</a></h3><p>菲涅尔区保留二次相位，掩模近处的泰伯自成像、接触式接近式光刻都靠它。扫描投影把物镜插在中间，有意走到夫琅禾费，好让光瞳成为空间频率的坐标系。本课两条都要：积分是一条，后课只取远场极限去谈级次。</p><p><span class="marginnote">\\(e^{ikR}/R\\) 的 \\(1/R\\) 是球面波振幅；相位才是干涉的主角。丢掉相位只加强度，就退化成非相干的「几何照度」，衍射条纹全部消失。</span></p>',18)),(t(),B(n,null,{default:e(()=>[o(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20HH%5B%22%E4%BA%A5%E5%A7%86%E9%9C%8D%E5%85%B9%E6%96%B9%E7%A8%8B%22%5D%20--%3E%20BV%5B%22%E5%AD%94%E5%BE%84%E8%BE%B9%E5%80%BC%22%5D%0A%20%20BV%20--%3E%20HF%5B%22%E6%83%A0%E6%9B%B4%E6%96%AF%E2%80%93%E8%8F%B2%E6%B6%85%E5%B0%94%E7%A7%AF%E5%88%86%22%5D%0A%20%20HF%20--%3E%20FR%5B%22%E8%8F%B2%E6%B6%85%E5%B0%94%20%2F%20%E5%A4%AB%E7%90%85%E7%A6%BE%E8%B4%B9%22%5D%0A%20%20FR%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%A9%BA%E9%97%B4%E9%A2%91%E7%8E%87%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"铬缝把入射平面波截断。截断后的场不能再只沿原方向走：积分核把每个面元的子波送到所有允许的 \\(k_z\\) 实数方向，观察点是这些子波的相干叠加。亮暗条纹来自光程差，不是来自「光线拐弯」。上一课的平面波基，现在可以读成：把积分核做傅里叶变换，子波包变成角谱。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"数字实例：\\(\\lambda=193\\) nm、面元间隔 \\(d=1\\ \\mu\\mathrm{m}\\) 时，两列子波在偏转角 \\(\\theta\\) 满足 \\(d\\sin\\theta=m\\lambda\\) 处同相叠加：第一级 \\(\\sin\\theta=0.193\\)，\\(\\theta\\approx 11°\\)。换个 \\(d\\) 或 \\(\\lambda\\) 一眼看出级次往哪跑——这正是后课「空间频率轴」的雏形。")],-1)),(t(),B(n,null,{default:e(()=>[o(r,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20SLIT%5B%22%E9%93%AC%E7%BC%9D%E6%88%AA%E6%96%AD%E5%85%A5%E5%B0%84%E5%B9%B3%E9%9D%A2%E6%B3%A2%22%5D%20--%3E%20SRC%5B%22%E7%BC%9D%E4%B8%8A%E6%AF%8F%E4%B8%AA%E9%9D%A2%E5%85%83%E6%88%90%E4%B8%BA%E7%90%83%E9%9D%A2%E5%AD%90%E6%B3%A2%E6%BA%90%22%5D%0A%20%20SRC%20--%3E%20OUT%5B%22%E5%AD%90%E6%B3%A2%E5%90%91%E5%90%84%E5%85%81%E8%AE%B8%E6%96%B9%E5%90%91%E5%8F%91%E5%B0%84%22%5D%0A%20%20OUT%20--%3E%20PD%7B%22%E5%88%B0%E8%A7%82%E5%AF%9F%E7%82%B9%E7%9A%84%E5%85%89%E7%A8%8B%E5%B7%AE%EF%BC%9F%22%7D%0A%20%20PD%20--%20%22%E5%90%8C%E7%9B%B8%EF%BC%9A%E7%A8%8B%E5%B7%AE%20%3D%20m%CE%BB%22%20--%3E%20BRIGHT%5B%22%E7%9B%B8%E9%95%BF%20%E2%86%92%20%E4%BA%AE%E7%BA%B9%22%5D%0A%20%20PD%20--%20%22%E5%8F%8D%E7%9B%B8%EF%BC%9A%E7%A8%8B%E5%B7%AE%20%3D%20(m%2B1%2F2)%CE%BB%22%20--%3E%20DARK%5B%22%E7%9B%B8%E6%B6%88%20%E2%86%92%20%E6%9A%97%E7%BA%B9%22%5D%0A%20%20TILT%5B%22%E5%80%BE%E6%96%9C%E5%9B%A0%E5%AD%90%20K(%CE%B8)%20%E5%8E%8B%E4%BD%8E%E5%A4%A7%E8%A7%92%E5%BA%A6%E8%B4%A1%E7%8C%AE%22%5D%20--%3E%20PAT%0A%20%20BRIGHT%20--%3E%20PAT%5B%22%E7%9B%B8%E5%B9%B2%E5%8F%A0%E5%8A%A0%E6%88%90%E8%A1%8D%E5%B0%84%E5%9B%BE%E6%A0%B7%22%5D%0A%20%20DARK%20--%3E%20PAT%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p>倾斜因子压掉大角度贡献，对应后课「可传播频率不超过 \\(n/\\lambda\\)」的萌芽——擦边方向的子波接近倏逝，积分自动变弱。本课不引入 \\(\\mathrm{NA}\\)；截止要等光瞳课才变成合同上的数。</p><p><span class="marginnote">常见误区：初学者容易以为暗纹是「光被什么东西挡住或吸掉了」。实际上每个观察点的场都是子波相干叠加的结果——暗纹处子波彼此相消，并没有能量被吃掉，总能量重新分配到了亮纹里。</span></p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到衍射，先承认场由孔径上的惠更斯积分（或等价角谱）决定，不再从麦克斯韦方程重推单色波。物面 \\(U\\) 可以是复透过率乘照明；照明若有许多互不相干方向，强度在积分之后再加，那是部分相干课的缺口。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不管透镜玻璃里的折射面如何逐面追迹：物镜被后课收成光瞳函数，等于在夫琅禾费域乘一个窗。也不处理有限带宽：每个 \\(\\omega\\) 各做一次亥姆霍兹，再对光谱积分，是色差课的事。Kirchhoff 在边缘上场值跳跃，严格电磁学不成立，但对开口远大于波长的铬缝，标量积分已经够后课用。</p><p>不要把惠更斯原理理解成「波前真的铺满点光源」的本体论；它是亥姆霍兹边值的构造。点扩散、艾里斑、瑞利 CD，一律还没有定义。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>亥姆霍兹是局部约束；成像要的是孔径到观察点的积分核。</li><li>惠更斯–菲涅尔（及 Kirchhoff / Rayleigh–Sommerfeld）把上一课的 \\(U\\) 推进到下游。</li><li>相位仍是 \\(k_0\\) 乘光程；近场取菲涅尔，光瞳取夫琅禾费。</li><li>角谱是同一积分的平面波基底，下一课给它装上空间频率轴。</li><li>本课不引入 \\(\\mathrm{NA}\\)，不写产线 CD 公式。</li><li>出处：Born &amp; Wolf, <em>Principles of Optics</em>（标量衍射与惠更斯–菲涅尔）。</li></ul>',9))])}const T=A(p,[["render",d]]);export{b as __pageData,T as default};
